      rendererSource=await readFile(new URL('./briefing-render.mjs',import.meta.url));
    const producer={module:digest(helperSource),renderer:digest(rendererSource)};
    let record=found.record??{id:randomUUID(),kind:'exports',exportKind:'briefing',revision:1,...found.pin,
      sourceId:comparison.id,sourceSha256:comparison.sha256,
      creation:{action:'briefings.create',payload:clone(input)},createdAt:now(),updatedAt:now(),
      status:'BUILDING',sha256:null,files:[],
      briefing:{title,audience,notes,rowsPerPage,sourceExportId:sourceExport.id,
        sourceExportSha256:sourceExport.sha256,producer}};
    if(record.sourceSha256!==comparison.sha256||record.briefing?.sourceExportSha256!==sourceExport.sha256)
      throw fault('BRIEFING_SOURCE_CHANGED','The retained briefing must keep its exact original comparison delivery.',409);
    if(identity(record.briefing.producer)!==identity(producer))
      throw fault('BRIEFING_PRODUCER_CHANGED','Continue this briefing with its original source version, or create a new request for the current renderer.',409);
    if(!found.record)await save('exports',record);
    const {createFiscalBriefing}=await import('./briefing.mjs');
    // This action already owns the serial writer. Lend the SAME original read functions;
    // a nested public dispatch would otherwise wait behind its own accepted action.
    const borrowed={
      snapshot,
      file,
      async dispatch(action,payload) {
        if(action!=='comparisons.get')throw fault('BRIEFING_READ_ACTION','The briefing borrows the original comparison reader.',409);
        return {result:await comparisonPage(payload)};
      }
    };
    const result=await createFiscalBriefing({directory,model:borrowed,
      comparisonId:comparison.id,expectedComparisonSha256:comparison.sha256,exportId:sourceExport.id,
      outputDirectory:directory+'-briefings',operationId:'workspace-'+record.id,
      createdAt:record.createdAt,title,audience,notes,rowsPerPage});
    if(result.state!=='COMPLETE'||!result.archive||result.comparisonSha256!==comparison.sha256)
      throw fault('BRIEFING_NOT_COMPLETE','Continue the original briefing until its complete archive is sealed.',409);
    const manifestBytes=await readPrivate(join(result.directory,'manifest.json'),32*MiB);
    if(digest(manifestBytes)!==result.manifestSha256)
      throw fault('BRIEFING_MANIFEST_CHANGED','The original briefing manifest changed before delivery.',409);
    const manifest=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(manifestBytes));
    const sources=[{source:{...result.archive,name:'briefing.tar.gz',mime:'application/gzip'},target:'briefing.tar.gz'},
      {source:{path:join(result.directory,'manifest.json'),size:manifestBytes.length,
        sha256:result.manifestSha256,mime:'application/json'},target:'briefing-manifest.json'}];
    for(const name of ['briefing.json','briefing.md','dated-measures.csv']) {
      const item=manifest.files.find(value=>value.path===name);
      if(!item)throw fault('BRIEFING_FILE_MISSING','The completed briefing must include '+name+'.',409);
      sources.push({source:{...item,path:join(result.directory,name)},target:name});
    }
    record={...record,briefing:{...record.briefing,operationId:result.operationId,
      manifestSha256:result.manifestSha256,archiveSha256:result.archive.sha256,files:result.files,bytes:result.bytes}};
    return finishExport(record,sources,'Complete original Fiscal comparison briefing: '+title+
      '. Extract briefing.tar.gz and open index.html for the offline report, dated-measure CSV, every original row page and complete source delivery. '+
      'The authored audience and notes accompany the exact reviewed comparison; decimal values and source-unit interpretations are preserved.');
  }
  async function makeRefreshDelivery(run,input) {
    const payload={id:run.id,sha256:run.sha256,requestId:input.requestId};
    const found=requestExisting('exports','refresh.delivery',payload);
    if(found.record?.status==='READY')return exportView(found.record);
    if(!run.completion||identity(run.completion)!==run.sha256)
      throw fault('REFRESH_HANDOVER_CHANGED','Complete and retain the selected refresh before its handover.',409);
    if(!found.record&&records.exports.size>=limits.maxExports)
      throw fault('EXPORT_CAPACITY','Keep the full original refresh within this workspace’s export capacity.',409);
    const sourceExport=get('exports',run.sourceExport.id),briefing=get('exports',run.briefing.id);
    if(sourceExport.status!=='READY'||sourceExport.sha256!==run.sourceExport.sha256||
       sourceExport.exportKind!=='comparison'||sourceExport.sourceId!==run.comparison.id||
       sourceExport.sourceSha256!==run.comparison.sha256||
       briefing.status!=='READY'||briefing.sha256!==run.briefing.sha256||
       briefing.exportKind!=='briefing'||briefing.sourceId!==run.comparison.id)
      throw fault('REFRESH_DELIVERY_SELECTION','Keep this run’s exact comparison delivery and completed briefing.',409);
    const record=found.record??{id:randomUUID(),kind:'exports',exportKind:'refresh',revision:1,...found.pin,
      sourceId:run.id,sourceSha256:run.sha256,creation:{action:'refresh.delivery',payload},
      createdAt:run.completion.completedAt,updatedAt:now(),status:'BUILDING',sha256:null,files:[]};
    if(!found.record)await save('exports',record);
    const sources=[
      {target:'refresh-plan.json',data:bytes({schema:'stellar-forge.fiscaldata-refresh-plan.v1',id:run.planId,
        revision:run.planRevision,sha256:run.planSha256,definition:run.definition}),mime:'application/json'},
      {target:'refresh-run.json',data:bytes(run.completion),mime:'application/json'},
      {target:'FIELD_RULES.md',data:Buffer.from('# '+run.definition.name+'\n\n'+
        'This delivery retains the exact source revision, selected fields, original units, scale annotations, null markers, row keys and query rules in refresh-plan.json. '+
        'refresh-run.json binds the dated query, actual capture, reviewed edition, comparison and briefing. '+
        'The previous baseline remains selected until the operator explicitly promotes a complete run in the saved plan.\n\n'+
        'Extract briefing.tar.gz and open index.html for the complete offline report. comparison-source.tar.gz contains every original retained comparison source. '+
        'Dated stock observations describe values on their stated dates; adding daily balances is not a period total.\n'),
        mime:'text/markdown; charset=utf-8'},
      {source:await file('export',sourceExport.id,'delivery.tar.gz'),target:'comparison-source.tar.gz'}
    ];
    for(const name of ['briefing.tar.gz','briefing.json','briefing.md','briefing-manifest.json','dated-measures.csv'])
      sources.push({source:await file('export',briefing.id,name),target:name});
    return finishExport(record,sources,'Complete saved refresh '+run.id+' for '+run.definition.name+
      '. The frozen plan, actual dated source query, exact reviewed comparison, offline briefing and complete original source archive are included.');
  }

  async function merchantSources(edition,sourceClosureVersion) {
    const sources=await exportSources('editions',edition.id);
    if(sourceClosureVersion!==1)return sources; // Resume an original pre-closure export unchanged.
    const original=sources.find(item=>item.target==='source.json');
    if(!original?.source)throw fault('EDITION_SOURCE_MISSING','The original edition provenance is required for publication.',409);
    const sourceBytes=await readPrivate(original.source.path,Math.max(original.source.size+1,MiB));
    const provenance=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(sourceBytes));
    if(!object(provenance)||provenance.schema!=='stellar-forge.fiscaldata-edition-source.v1'||
        provenance.editionId!==edition.id||provenance.captureSha256!==edition.captureSha256)
      throw fault('EDITION_SOURCE_CHANGED','The merchant provenance must bind this exact retained edition.',409);
    sources.push({...original,target:'original-edition/source.json'});
    const nativeFiles=new Set(['dataset.csv','dataset.json','seller.json','source.json','binding.json','original-seller.json']);
    const sourceFiles=sources.filter(item=>!nativeFiles.has(item.target)).map(item=>({
      path:item.target,bytes:item.data?item.data.length:item.source.size,
      sha256:item.data?digest(item.data):item.source.sha256
    })).sort((left,right)=>left.path<right.path?-1:left.path>right.path?1:0);
    // The original edition metadata stays byte-exact beside the publisher declaration.
    // Every raw response/review member is explicit; manifests do not imply nested files.
    return sources.map(item=>item===original?{target:'source.json',data:bytes({...provenance,sourceFiles}),mime:'application/json'}:item);
  }
  async function configureMerchant(input) {
    only(input,['editionId','origin','path','payment','requestId']);
    const edition=get('editions',input.editionId),found=requestExisting('exports','merchant.configure',input);
    if(found.record?.status==='READY')return exportView(found.record);
    if(!found.record&&records.exports.size>=limits.maxExports)throw fault('EXPORT_CAPACITY','Open another workspace for more retained exports.',409);
    const native=await nativeDataset(edition),{buildDatasetSellerConfig}=await import('../dataset-cli.mjs');
    const seller=await buildDatasetSellerConfig(native,{origin:input.origin,path:input.path,payment:input.payment});
    let record=found.record??{id:randomUUID(),kind:'exports',exportKind:'merchant',revision:1,...found.pin,
      sourceId:edition.id,sourceSha256:edition.sha256,sourceClosureVersion:1,creation:{action:'merchant.configure',payload:clone(input)},createdAt:now(),updatedAt:now(),status:'BUILDING',
      origin:input.origin,path:input.path,payment:clone(input.payment),sha256:null,files:[]};
    if(!found.record)await save('exports',record);
    const sources=await merchantSources(edition,record.sourceClosureVersion);sources.push({target:'seller.json',data:bytes(seller),mime:'application/json'});
    const output=await finishExport(record,sources,'Original SF30 merchant dataset '+edition.id+
      ' with the operator’s explicit public payment terms. The adjacent dataset.csv, dataset.json, source.json and seller.json are the native publisher inputs. Full captured Treasury responses and reviewed units are included.');
    edition.merchant={id:output.id,sha256:output.sha256,origin:input.origin,path:input.path,configuredAt:record.createdAt};
    // This is a delivery reference; it does not rewrite the sealed source edition or its snapshot.
    await save('editions',edition);return output;
  }
  async function publicDeliveryFiles(root,prefix='delivery') {
    if(await realpath(root)!==root)throw fault('ACQUISITION_PATH','Use the original buyer delivery directory.',409);
    const result=[];
    async function walk(path,parts){
      for(const entry of (await readdir(path,{withFileTypes:true})).sort((a,b)=>a.name.localeCompare(b.name))){
        if(!safeName(entry.name))throw fault('ACQUISITION_FILE_NAME','The original delivery contains an unsupported filename.',409);
        const next=join(path,entry.name),names=[...parts,entry.name];
        if(entry.isDirectory())await walk(next,names);
        else if(entry.isFile()){
          const stat=await lstat(next);if(stat.isSymbolicLink()||stat.nlink!==1)throw fault('ACQUISITION_FILE_IDENTITY','Use the retained original delivery files.',409);
          const h=await hashPrivate(next,256*MiB);
          const mime=entry.name.endsWith('.json')?'application/json':entry.name.endsWith('.csv')?'text/csv; charset=utf-8':
            entry.name.endsWith('.jsonl')?'application/x-ndjson':entry.name.endsWith('.md')?'text/markdown; charset=utf-8':'application/octet-stream';
          result.push({source:{path:next,name:entry.name,mime,sha256:h.hash,size:h.bytes},target:[prefix,...names].join('/')});
        }else throw fault('ACQUISITION_FILE_TYPE','The original delivery must contain regular files and directories.',409);
        if(result.length>20000)throw fault('ACQUISITION_FILE_CAPACITY','The original delivery exceeds the configured export file capacity.',413);
      }
    }
    await walk(root,[]);return result;
  }
  async function retainAcquisition(input) {
    assertId(input.id);
    const session=join(directory,'publisher','sessions',input.id),manifest=join(session,'acquisition-manifest.json'),delivery=join(session,'delivery');
    if(input.manifest!==manifest||input.delivery!==delivery)
      throw fault('ACQUISITION_SOURCE_IDENTITY','The original buyer returned an unexpected retained delivery location.',409);
    const sourceManifest=await hashPrivate(manifest,32*MiB),sources=await publicDeliveryFiles(delivery);
    sources.push({source:{path:manifest,name:'session-manifest.json',mime:'application/json',size:sourceManifest.bytes,sha256:sourceManifest.hash},
      target:'session-manifest.json'});
    const sourceSha256=identity(sources.map(item=>({path:item.target,size:item.source.size,sha256:item.source.sha256})));
    const found=requestExisting('exports','publisher.buyer.export',{requestId:input.id+':'+sourceSha256,id:input.id,sourceSha256});
    if(found.record?.status==='READY')return exportView(found.record);
    if(!found.record&&records.exports.size>=limits.maxExports)throw fault('EXPORT_CAPACITY','The original buyer delivery is retained; use a larger export capacity for its complete archive.',409);
    const record=found.record??{id:randomUUID(),kind:'exports',exportKind:'acquisition',revision:1,...found.pin,
      sourceId:input.id,sourceSha256,creation:{action:'publisher.buyer.export',payload:{id:input.id}},createdAt:now(),updatedAt:now(),status:'BUILDING',sha256:null,files:[]};
    if(!found.record)await save('exports',record);
    return finishExport(record,sources,'Complete original SF88/SF100 buyer acquisition '+input.id+
      '. The native session manifest and every file in its delivered dataset are retained byte for byte. The original buyer engine remains responsible for acquisition, accounting and recovery.');
  }
  async function file(kind,id,name) {
    if(closed)throw fault('WORKSPACE_CLOSED','Reopen the private workspace.',409);
    if(!safeName(name))throw fault('DOWNLOAD_NAME','Choose a manifest-listed file.',404);
    if(kind==='publisher')return serial(()=>publisher.file(id,name));
    const groups={capture:'captures',edition:'editions',comparison:'comparisons',export:'exports'},group=groups[kind];
    if(!group)throw fault('DOWNLOAD_KIND','Choose a retained workspace download.',404);
    const record=get(group,id),descriptors=group==='captures'?await captureFiles(record):record.files;
    const descriptor=descriptors.find(value=>value.name===name);
    if(!descriptor)throw fault('DOWNLOAD_MISSING','This original item has no such retained file.',404);
    return verified(pathFor(group,id),descriptor);
  }
  async function dispatchAction(action,input) {
    if(typeof action==='string'&&action.startsWith('refresh.')){
      if(action==='refresh.delivery'){
        only(input,['id','sha256','requestId']);const run=get('refresh-runs',input.id);
        if(run.sha256!==input.sha256)throw fault('REFRESH_HANDOVER_CHANGED','Choose the exact retained refresh handover.',409);
        return makeRefreshDelivery(run,input);
      }
      return refreshPlans.dispatch(action,input);
    }
    switch(action){
      case 'catalog.refresh':only(input,[]);return refreshCatalog();
      case 'sources.save':return saveSource(input);
      case 'sources.probe':return probeSource(input);
      case 'captures.start':return beginCapture(input);
      case 'captures.pause':return captureIntent('pause',input);
      case 'captures.resume':return captureIntent('resume',input);
      case 'captures.cancel':return captureIntent('cancel',input);
      case 'captures.get':{only(input,['id']);const record=get('captures',input.id);return{...captureView(record),source:record.source,
        metadata:record.metadata,pageRecords:record.pageRecords,attempts:record.attempts,duplicates:record.duplicates,
        consistency:record.consistency,files:(await captureFiles(record)).map(({relative,...file})=>file)};}
      case 'captures.rows':return rowsPage('captures',input);
      case 'editions.create':return createEdition(input);
      case 'editions.review':return reviewEdition(input);
      case 'editions.build':return buildEdition(input);
      case 'editions.get':{only(input,['id']);const record=get('editions',input.id);
        const fields=record.status==='DRAFT'?(record.sourceFields??record.fields).map(field=>{
          const selected=record.fields.find(value=>value.source===field.source);return{...(selected??field),included:!!selected};}):record.fields;
        return{...record,fields,files:fileRecords(record)};}
      case 'editions.rows':return rowsPage('editions',input);
      case 'editions.query':return queryEdition(input);
      case 'comparisons.create':return createComparison(input);
      case 'comparisons.get':return comparisonPage(input);
      case 'exports.create':return makeExport(input);
      case 'briefings.create':return makeBriefing(input);
      case 'merchant.configure':return configureMerchant(input);
      default:
        if(typeof action==='string'&&action.startsWith('publisher.'))return publisher.act(action,input);
        throw fault('ACTION_UNKNOWN','Choose an action exposed by this Fiscal Data workspace.',404);
    }
  }
  async function dispatch(action,payload={}) {
    if(closing||closed)throw fault('WORKSPACE_CLOSED','The workspace is draining; reopen it before another action.',409);
    if(!object(payload))throw fault('ACTION_PAYLOAD','Use a JSON object for the action payload.');
    const result=await serial(async()=>{
      try{return await dispatchAction(action,clone(payload));}
      catch(error){
        const group=action==='comparisons.create'?'comparisons':['exports.create','briefings.create','merchant.configure','publisher.buyer.export'].includes(action)?'exports':null;
        if(group){
          const failed=[...records[group].values()].find(value=>value.creation?.action===action&&identity(value.creation.payload)===identity(payload)&&value.status!=='READY');
          if(failed){failed.status='FAILED';failed.error=errorView(error);failed.revision++;failed.updatedAt=now();await save(group,failed).catch(()=>{});}
        }
        throw error;
      }
    });
    return {result,state:await snapshot()};
  }
  async function startWorker() {
    if(closing||closed)throw fault('WORKSPACE_CLOSED','Reopen the original workspace.',409);
    workerEnabled=true;kick();return {running:true};
  }
  async function close() {
    if(closePromise)return closePromise;
    closing=true;workerEnabled=false;controller?.abort();
    closePromise=(async()=>{
      try{
        await workerPromise;await tail.catch(()=>{});await publisher.close();datasets.clear();
      }finally{closed=true;await unlock();}
    })();return closePromise;
  }
  return {snapshot,dispatch,file,startWorker,close};
}

// MIT. Local operator surface for the original Fiscal Data workspace.
import {createServer} from 'node:http';
import {readFile,open} from 'node:fs/promises';
import {constants} from 'node:fs';
import {randomBytes,timingSafeEqual} from 'node:crypto';
import {pipeline} from 'node:stream/promises';
import {openFiscalWorkspace} from './workspace-model.mjs';

const fault=(code,message,status=400)=>Object.assign(new Error(message),{code,status});
const assetTypes={'index.html':'text/html; charset=utf-8','app.js':'text/javascript; charset=utf-8','refresh.js':'text/javascript; charset=utf-8','style.css':'text/css; charset=utf-8'};
const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
const headers={'cache-control':'no-store','x-content-type-options':'nosniff',
  'referrer-policy':'no-referrer','cross-origin-resource-policy':'same-origin',
  'content-security-policy':"default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'"};

export async function createFiscalWorkspaceHandler({model,origins,basePath='',token=randomBytes(32).toString('hex'),identity=null}={}) {
  if(!model||!Array.isArray(origins)||!origins.length||!/^(?:\/[A-Za-z0-9_-]+)*$/.test(basePath))
    throw fault('WORKSPACE_ORIGIN_REQUIRED','Provide the original model and an explicit local workspace origin.');
  if(identity!==null&&!object(identity))throw fault('WORKSPACE_IDENTITY_REQUIRED','Provide an original managed application identity.');
  const managedIdentity=identity===null?null:structuredClone(identity);
  const allowed=new Set(origins.map(value=>new URL(value).origin));
  const hosts=new Set([...allowed].map(value=>new URL(value).host));
  const assets=new Map(await Promise.all(Object.entries(assetTypes).map(async([name,type])=>
    [name,{type,bytes:await readFile(new URL('./workspace-ui/'+name,import.meta.url))}])));
  const cookieName='sf_fiscal_'+new URL([...allowed][0]).port;
  const cookie=()=>cookieName+'='+token+'; Path='+(basePath?basePath+'/':'/')+'; HttpOnly; SameSite=Strict';
  const validToken=value=>{const provided=Buffer.from(String(value??'')),expected=Buffer.from(token);
    return provided.length===expected.length&&timingSafeEqual(provided,expected);};
  const authenticated=req=>validToken(req.headers['x-fiscaldata-session'])||
    validToken(String(req.headers.cookie??'').split(';').map(value=>value.trim()).find(value=>value.startsWith(cookieName+'='))?.slice(cookieName.length+1));
  const reading=new Set(); let closing=false;
  const handler=async(req,res)=>{
    function reply(status,type,value,extra={}) {
      if(res.destroyed)return;
      const bytes=Buffer.isBuffer(value)?value:Buffer.from(typeof value==='string'?value:JSON.stringify(value));
      res.writeHead(status,{...headers,'content-type':type,'content-length':String(bytes.length),...extra});
      res.end(req.method==='HEAD'?undefined:bytes);
    }
    const json=(status,value,extra={})=>reply(status,'application/json; charset=utf-8',value,extra);
    try {
      if(closing)throw fault('WORKSPACE_CLOSING','The workspace is closing.',503);
      if(!hosts.has(req.headers.host)||req.headers.origin&&!allowed.has(req.headers.origin)||
        ['cross-site','same-site'].includes(req.headers['sec-fetch-site']))
        throw fault('WORKSPACE_ORIGIN_REQUIRED','Open this workspace through its local address.',403);
      const url=new URL(req.url,'http://'+req.headers.host),pathname=url.pathname;
      if(basePath&&pathname!==basePath&&!pathname.startsWith(basePath+'/'))return false;
      const route=pathname.slice(basePath.length)||'/';
      if(url.search)throw fault('INVALID_WORKSPACE_URL','This route does not accept query parameters.');
      if(basePath&&pathname===basePath) {
        if(!['GET','HEAD'].includes(req.method))throw fault('NOT_FOUND','Route not found.',404);
        reply(307,'text/plain','Open the Fiscal Data workspace.',{location:basePath+'/'});return true;
      }
      if(['GET','HEAD'].includes(req.method)) {
        const asset=assets.get(route==='/'?'index.html':route.slice(1));
        if(asset){reply(200,asset.type,asset.bytes,asset.type.startsWith('text/html')?{'set-cookie':cookie()}:{});return true;}
        if(route==='/api/state'){json(200,{...await model.snapshot(),...(managedIdentity?{managedApplication:{workspaceAlias:managedIdentity.workspaceAlias,operator:managedIdentity.operator,instanceId:managedIdentity.instanceId}}:{}),sessionToken:token},{'set-cookie':cookie()});return true;}
        if(route==='/api/identity'&&managedIdentity!==null){
          if(!authenticated(req))throw fault('WORKSPACE_SESSION_REQUIRED','Open this workspace before inspecting its original managed identity.',403);
          json(200,managedIdentity);return true;
        }
        const match=/^\/api\/files\/([^/]+)\/([^/]+)\/([^/]+)$/.exec(route);
        if(match) {
          if(!authenticated(req))throw fault('WORKSPACE_SESSION_REQUIRED','Open this workspace before downloading its retained files.',403);
          const parts=match.slice(1).map(value=>{
            let decoded;try{decoded=decodeURIComponent(value);}catch{throw fault('INVALID_FILE','Invalid file selection.');}
            if(!decoded||decoded.length>256||/[\/\\\u0000-\u001f\u007f]/.test(decoded)||decoded==='.'||decoded==='..')
              throw fault('INVALID_FILE','Select a retained workspace file.');
            return decoded;
          });
          const file=await model.file(...parts);
          if(!file||typeof file.path!=='string'||typeof file.name!=='string'||
            !Number.isSafeInteger(file.size)||file.size<0||!/^[a-f0-9]{64}$/.test(file.sha256??''))
            throw fault('INVALID_FILE_RECORD','The selected file has no complete retained identity.',409);
          const handle=await open(file.path,constants.O_RDONLY|(constants.O_NOFOLLOW??0));
          try {
            const info=await handle.stat();
            if(!info.isFile()||info.size!==file.size)throw fault('FILE_CHANGED','The selected file changed. Refresh its edition.',409);
            const name=file.name.replace(/[^A-Za-z0-9._-]/g,'_').slice(0,200)||'fiscal-data-download';
            const mime=typeof file.mime==='string'&&/^[a-z0-9.+-]+\/[a-z0-9.+-]+(?:; charset=utf-8)?$/i.test(file.mime)?
              file.mime:'application/octet-stream';
            res.writeHead(200,{...headers,'content-type':mime,'content-length':String(file.size),
              'content-disposition':'attachment; filename="'+name+'"','x-content-sha256':file.sha256,
              etag:'"sha256-'+file.sha256+'"'});
            if(req.method==='HEAD')res.end();
            else await pipeline(handle.createReadStream({autoClose:false}),res);
          } finally {await handle.close();}
          return true;
        }
        throw fault('NOT_FOUND','Route not found.',404);
      }
      if(req.method!=='POST'){reply(405,'text/plain','Use GET or POST.',{allow:'GET, HEAD, POST'});return true;}
      if(route!=='/api/action')throw fault('NOT_FOUND','Route not found.',404);
      const provided=Buffer.from(String(req.headers['x-fiscaldata-session']??'')),expected=Buffer.from(token);
      if(provided.length!==expected.length||!timingSafeEqual(provided,expected))
        throw fault('WORKSPACE_SESSION_REQUIRED','Refresh the workspace before applying this action.',403);
      if(req.headers['content-type']?.split(';')[0].trim().toLowerCase()!=='application/json')
